<?php
require __DIR__ . '/config.php';
require_login();
$stmt=$pdo->prepare("SELECT * FROM orders WHERE customer_id=? ORDER BY created_at DESC"); $stmt->execute([$_SESSION['user']['id']]); $orders=$stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Orders | Joe Mart</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="brand" href="index.php">🛒 Joe Mart</a><nav><a href="index.php">Shop</a><a href="dashboard.php">Dashboard</a></nav></header><main class="container page"><h1>My Orders</h1><?php if(isset($_GET['placed'])): ?><p class="success">Your order has been placed successfully.</p><?php endif; ?><?php if(!$orders): ?><p class="empty">You have not placed any orders yet.</p><?php else: ?><div class="table-wrap panel"><table><tr><th>Order #</th><th>Date</th><th>Total</th><th>Status</th><th>Payment</th></tr><?php foreach($orders as $o): ?><tr><td>#<?= (int)$o['id'] ?></td><td><?= e($o['created_at']) ?></td><td><?= money($o['total']) ?></td><td><span class="pill"><?= e($o['status']) ?></span></td><td><?= e($o['payment_method']) ?> · <?= e($o['payment_status']) ?></td></tr><?php endforeach; ?></table></div><?php endif; ?></main></body></html>
